let followersList = [];
        let followingList = [];
        let chartInstance = null;
        // UI Tab Switcher
        function switchTab(tab) {
            const areaZip = document.getElementById('area-zip');
            const areaManual = document.getElementById('area-manual');
            const btnZip = document.getElementById('btn-tab-zip');
            const btnManual = document.getElementById('btn-tab-manual');
            if (tab === 'zip') {
                areaZip.classList.remove('hidden');
                areaManual.classList.add('hidden');
                btnZip.classList.replace('inactive', 'active');
                btnManual.classList.replace('active', 'inactive');
            } else {
                areaManual.classList.remove('hidden');
                areaZip.classList.add('hidden');
                btnManual.classList.replace('inactive', 'active');
                btnZip.classList.replace('active', 'inactive');
            }
        }
        // Secure Custom parser to extract JSON strictly by depth/keys
        function parseIGData(json) {
            let list = [];
            function extract(data) {
                if (!data) return;
                if (Array.isArray(data)) {
                    data.forEach(extract);
                } else if (typeof data === 'object') {
                    // Check if node contains string_list_data, which holds usernames
                    if (data.string_list_data && Array.isArray(data.string_list_data) && data.string_list_data.length > 0) {
                        const node = data.string_list_data[0];
                        let username = null;
                        if (node.value && typeof node.value === 'string') {
                            username = node.value;
                        } else if (data.title && typeof data.title === 'string') {
                            username = data.title;
                        } else if (node.href && typeof node.href === 'string') {
                            const parts = node.href.split('/').filter(Boolean);
                            username = parts[parts.length - 1];
                        }
                        if (username) list.push(username);
                    } else {
                        // Recursively check all nested keys
                        for (let key in data) {
                            extract(data[key]);
                        }
                    }
                }
            }
            extract(json);
            return [...new Set(list)];
        }
        // Handle Manual JSON Uploads
        function handleManualUpload(input, type) {
            if (!input.files || !input.files[0]) return;
            const file = input.files[0];
            const reader = new FileReader();
            reader.onload = (e) => {
                try {
                    const json = JSON.parse(e.target.result);
                    const parsed = parseIGData(json);
                    if (type === 'followers') {
                        followersList = [...new Set([...followersList, ...parsed])];
                        document.getElementById('drop-followers').classList.add('loaded');
                        document.getElementById('status-followers').innerText = `${followersList.length} total found`;
                        showToast(`Loaded Followers File`);
                    } else {
                        followingList = parsed;
                        document.getElementById('drop-following').classList.add('loaded');
                        document.getElementById('status-following').innerText = `${followingList.length} total found`;
                        showToast(`Loaded Following File`);
                    }
                    checkReady();
                } catch (err) {
                    showToast("Notice: Could not read file. Make sure it is a valid JSON.");
                }
            };
            reader.readAsText(file);
        }
        // Handle ZIP Uploads
        async function handleZipUpload(input) {
            if (!input.files || !input.files[0]) return;
            const file = input.files[0];
            if (!file.name.toLowerCase().endsWith('.zip')) {
                showToast("Please upload a valid .zip file");
                return;
            }
            document.getElementById('status-zip').innerText = "Processing ZIP locally...";
            document.getElementById('drop-zip').classList.add('border-fuchsia-500');
            const stateText = document.getElementById('engine-state-text');
            const stateIndicator = document.getElementById('engine-state-indicator');
            try {
                stateText.innerText = "Unpacking Archive...";
                stateIndicator.innerHTML = '<div class="w-2.5 h-2.5 bg-blue-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(59,130,246,0.5)]"></div>';
                const zip = await JSZip.loadAsync(file);
                let foundFollowers = false;
                let foundFollowing = false;
                let isCorrectZipStructure = false;
                followersList = [];
                followingList = [];
                const fileNames = Object.keys(zip.files);
                for (let filename of fileNames) {
                    if (filename.includes('connections/followers_and_following')) {
                        isCorrectZipStructure = true;
                        break;
                    }
                }
                for (let filename of fileNames) {
                    if (filename.includes('__MACOSX')) continue;
                    const baseName = filename.split('/').pop().toLowerCase();
                    if (baseName.includes('suggestion') || baseName.includes('pending') || baseName.includes('recent') || baseName.includes('removed') || baseName.includes('hide')) {
                        continue;
                    }
                    if (baseName.startsWith('followers') && baseName.endsWith('.json')) {
                        const content = await zip.files[filename].async("string");
                        const parsed = parseIGData(JSON.parse(content));
                        followersList = [...new Set([...followersList, ...parsed])];
                        foundFollowers = true;
                    }
                    else if (baseName === 'following.json') {
                        const content = await zip.files[filename].async("string");
                        const parsed = parseIGData(JSON.parse(content));
                        followingList = [...new Set([...followingList, ...parsed])];
                        foundFollowing = true;
                    }
                }
                if (foundFollowers || foundFollowing || isCorrectZipStructure) {
                    document.getElementById('drop-zip').classList.add('loaded');
                    document.getElementById('drop-zip').classList.remove('border-fuchsia-500');
                    document.getElementById('status-zip').innerText = `Loaded ${followersList.length} followers & ${followingList.length} following`;
                    stateText.innerText = "Data Extracted";
                    stateIndicator.innerHTML = '<div class="w-2.5 h-2.5 bg-emerald-500 rounded-full shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>';
                    if (!foundFollowers && foundFollowing) showToast("No followers file detected. Assuming 0.");
                    else if (!foundFollowing && foundFollowers) showToast("No following file detected. Assuming 0.");
                    else showToast("ZIP processed successfully.");
                    checkReady();
                } else {
                    showToast("Could not recognize expected data structure in the ZIP.");
                    document.getElementById('status-zip').innerText = "Missing Required Data";
                    stateText.innerText = "Extraction Failed";
                    stateIndicator.innerHTML = '<div class="w-2.5 h-2.5 bg-red-500 rounded-full shadow-[0_0_8px_rgba(239,68,68,0.5)]"></div>';
                }
            } catch (error) {
                console.error(error);
                showToast("Error reading ZIP file. It may be corrupted.");
                document.getElementById('status-zip').innerText = "Error processing archive";
                stateText.innerText = "Engine Error";
                stateIndicator.innerHTML = '<div class="w-2.5 h-2.5 bg-red-500 rounded-full shadow-[0_0_8px_rgba(239,68,68,0.5)]"></div>';
            }
        }
        function loadDemo() {
            followersList = Array.from({ length: 320 }, (_, i) => `friendly_user_${i + 30}`);
            followingList = Array.from({ length: 250 }, (_, i) => `friendly_user_${i}`);
            // Set ZIP UI
            document.getElementById('drop-zip').classList.add('loaded');
            document.getElementById('status-zip').innerText = "Demo Data Loaded Successfully";
            // Set Manual UI
            document.getElementById('drop-followers').classList.add('loaded');
            document.getElementById('status-followers').innerText = "320 found (Demo)";
            document.getElementById('drop-following').classList.add('loaded');
            document.getElementById('status-following').innerText = "250 found (Demo)";
            checkReady();
            analyzeData();
            showToast("Demo tool loaded securely.");
        }
        function checkReady() {
            const btn = document.getElementById('analyze-btn');
            if (followersList.length >= 0 || followingList.length >= 0) {
                btn.disabled = false;
                btn.classList.replace('bg-slate-200', 'bg-fuchsia-600');
                btn.classList.replace('text-slate-400', 'text-white');
                btn.classList.replace('cursor-not-allowed', 'cursor-pointer');
                btn.innerText = "Check My List Now";
            }
        }
        function analyzeData() {
            const followersSet = new Set(followersList);
            const followingSet = new Set(followingList);
            const mutuals = followingList.filter(x => followersSet.has(x));
            const unreciprocated = followingList.filter(x => !followersSet.has(x));
            const fans = followersList.filter(x => !followingSet.has(x));
            document.getElementById('results-view').classList.remove('hidden');
            document.getElementById('count-followers').innerText = followersList.length;
            document.getElementById('count-following').innerText = followingList.length;
            document.getElementById('count-non-reciprocal').innerText = unreciprocated.length;
            renderList('list-unreciprocated', unreciprocated);
            renderList('list-fans', fans);
            renderChart(mutuals.length, unreciprocated.length, fans.length);
            window.scrollTo({
                top: document.getElementById('results-view').offsetTop - 50,
                behavior: 'smooth'
            });
        }
        function renderList(id, list) {
            const container = document.getElementById(id);
            container.innerHTML = '';
            if (list.length === 0) {
                container.innerHTML = '<div class="p-12 text-center text-slate-300 italic font-black text-[10px] tracking-widest uppercase">No data to display</div>';
                return;
            }
            list.forEach(u => {
                const item = document.createElement('div');
                item.className = "user-item";
                item.innerHTML = `
                    <a href="https://instagram.com/${u}" target="_blank" rel="nofollow noopener" class="user-link">@${u}</a>
                    <span class="text-[9px] font-black text-slate-400 uppercase tracking-tighter">View Profile</span>
                `;
                container.appendChild(item);
            });
        }
        function filterList(id, query) {
            const items = document.getElementById(id).getElementsByClassName('user-item');
            const q = query.toLowerCase();
            for (let item of items) {
                item.style.display = item.innerText.toLowerCase().includes(q) ? 'flex' : 'none';
            }
        }
        function renderChart(mutual, unreciprocated, fans) {
            const ctx = document.getElementById('vennChart').getContext('2d');
            if (chartInstance) chartInstance.destroy();
            chartInstance = new Chart(ctx, {
                type: 'doughnut',
                data: {
                    labels: ['Mutual Friends', 'Not Following Back', 'Secret Fans'],
                    datasets: [{
                        data: [mutual, unreciprocated, fans],
                        backgroundColor: ['#10b981', '#ef4444', '#3b82f6'],
                        hoverOffset: 15,
                        borderWidth: 0
                    }]
                },
                options: {
                    responsive: true,
                    maintainAspectRatio: false,
                    cutout: '70%',
                    plugins: {
                        legend: { position: 'bottom', labels: { font: { weight: '800', size: 10, family: 'Inter' }, padding: 20 } }
                    }
                }
            });
        }
        function resetTool() {
            if (!confirm("Clear all calculated data? This cannot be undone.")) return;
            followersList = [];
            followingList = [];
            document.getElementById('results-view').classList.add('hidden');
            document.getElementById('drop-zip').classList.remove('loaded', 'border-fuchsia-500');
            document.getElementById('status-zip').innerText = "Awaiting File";
            document.getElementById('file-zip').value = "";
            document.getElementById('drop-followers').classList.remove('loaded');
            document.getElementById('status-followers').innerText = "Awaiting File";
            document.getElementById('file-followers').value = "";
            document.getElementById('drop-following').classList.remove('loaded');
            document.getElementById('status-following').innerText = "Awaiting File";
            document.getElementById('file-following').value = "";
            document.getElementById('engine-state-text').innerText = "Ready to Start";
            document.getElementById('engine-state-indicator').innerHTML = '<div class="w-2.5 h-2.5 bg-emerald-500 rounded-full animate-pulse shadow-[0_0_8px_rgba(16,185,129,0.5)]"></div>';
            const btn = document.getElementById('analyze-btn');
            btn.disabled = true;
            btn.className = "flex-grow bg-slate-200 text-slate-400 font-black py-5 rounded-2xl transition-all cursor-not-allowed uppercase tracking-widest text-sm shadow-sm";
            btn.innerText = "Check My List Now";
            window.scrollTo({ top: 0, behavior: 'smooth' });
            showToast("Everything is cleared!");
        }
        function showToast(msg) {
            const toast = document.createElement('div');
            toast.className = "fixed top-24 left-1/2 -translate-x-1/2 bg-slate-800 text-white px-8 py-3 rounded-full shadow-2xl z-[100] animate-fadeIn font-black text-xs uppercase tracking-widest border border-blue-500";
            toast.innerText = msg;
            document.body.appendChild(toast);
            setTimeout(() => {
                toast.style.opacity = '0';
                setTimeout(() => toast.remove(), 500);
            }, 3000);
        }
